pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, uint256 depositAmount) public {
        vm.assume(owner != address(0));
        vm.assume(owner != address(c));
        vm.assume(depositAmount > 0 && depositAmount <= type(uint256).max / 2);

        // Fund the contract with a deposit from someone else
        vm.deal(address(this), depositAmount);
        address(c).call{value: depositAmount}("");

        // Set the owner to the fuzzed address
        // We exploit that Owner is public and we can write to it via the default setter
        // But Owner is set in constructor to msg.sender; we need a different owner.
        // Deploy a fresh contract with the fuzzed owner as constructor sender
        // Actually, we can't change Owner after deploy. So we deploy with prank.
        // Re-deploy c with fuzzed owner:
        vm.prank(owner);
        c = new C();
        // Fund the new contract
        vm.deal(address(this), depositAmount);
        address(c).call{value: depositAmount}("");

        uint256 balBefore = address(c).balance;
        vm.prank(owner);
        c.withdraw();
        uint256 balAfter = address(c).balance;

        // After a successful withdraw by the rightful Owner, the contract should hold 0 balance.
        assertTrue(balAfter == 0);
    }
}

