pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, uint256 amount) public {
        // 1. Keep the domain wide: ensure owner is not zero address and can receive ether
        vm.assume(owner != address(0));
        vm.assume(owner != address(this));
        vm.assume(owner != address(c));
        // Bound amount to avoid overflow and ensure it's within reasonable limits
        amount = bound(amount, 1, 1_000_000 ether);

        // 2. Setup: deploy c with a different msg.sender as Owner, then fund it
        vm.deal(address(c), amount);
        // Record owner's balance before the operation
        uint256 ownerBalanceBefore = owner.balance;
        uint256 contractBalanceBefore = address(c).balance;

        // 3. The Owner initiates the withdraw
        vm.prank(owner);
        c.withdraw();

        // 4. Assertion: After a successful withdraw by Owner, the Owner's ETH balance
        // must increase by exactly the contract's balance before the call (ignoring gas).
        // The buggy version sends to msg.sender (which may differ from Owner in some calls),
        // so this invariant breaks when the fuzzer picks a prank where msg.sender != Owner.
        // We check the post-condition directly.
        assertTrue(owner.balance == ownerBalanceBefore + contractBalanceBefore);
    }
}

