pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address caller, uint256 amount) public {
        vm.assume(owner != address(0));
        vm.assume(caller != address(0));
        vm.assume(amount > 0);
        vm.assume(owner != caller);
        c = new C();
        // Make the fuzzed owner the contract owner
        // Set up the contract with some Ether and change owner via direct storage? No vm.store.
        // Instead, deploy fresh and fund it. We cannot change owner after deploy, so we use the default owner (address(this)).
        // But the fuzzed owner must be the Owner. So we must prank as the fuzzed owner to deploy.
        // We re-deploy inside the test, pranking as the fuzzed owner.
        vm.startPrank(owner);
        c = new C();
        vm.stopPrank();
        vm.assume(address(c).balance == 0);
        // Fund the contract with amount
        vm.deal(caller, amount);
        vm.prank(caller);
        (bool funded,) = address(c).call{value: amount}("");
        require(funded);
        // Now caller is not necessarily owner; withdraw must be called by owner
        vm.prank(owner);
        try c.withdraw() { } catch { }
        // After owner calls withdraw, contract balance must be zero
        assertTrue(address(c).balance == 0);
    }
}

