pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address other, uint256 deposit) public {
        vm.assume(owner != address(0));
        vm.assume(other != address(0));
        vm.assume(owner != other);
        vm.assume(deposit > 0 && deposit <= 1000 ether);
        // Deploy fresh contract with pre-funded owner
        c = new C();
        vm.deal(owner, deposit * 2);
        vm.prank(owner);
        (bool okDep,) = address(c).call{value: deposit}("");
        require(okDep, "deposit fail");
        uint256 ownerBalBefore = owner.balance;
        uint256 cBalBefore = address(c).balance;
        // Owner calls withdraw
        vm.prank(owner);
        c.withdraw();
        uint256 ownerBalAfter = owner.balance;
        uint256 cBalAfter = address(c).balance;
        // Ether conservation: owner delta + contract delta must be zero
        // owner delta + c delta = (ownerBalAfter - ownerBalBefore) + (cBalAfter - cBalBefore) == 0
        uint256 ownerDelta = ownerBalAfter - ownerBalBefore;
        uint256 cDelta = cBalAfter - cBalBefore;
        assertTrue(ownerDelta + cDelta == 0, "ether conservation violated");
    }
}

