pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, bytes calldata data, uint256 ethAmount) public {
        // restrict msg.value to avoid overflow and keep it admissible
        vm.assume(ethAmount <= type(uint128).max);

        // set up the owner
        address owner = c.Owner();
        vm.deal(owner, ethAmount);

        // record balance before Command
        uint256 balanceBefore = address(c).balance;

        // call Command as owner with fuzzed parameters
        vm.prank(owner);
        c.Command{value: ethAmount}(adr, data);

        uint256 balanceAfter = address(c).balance;
        // Rule: balance change = balanceAfter - balanceBefore should be 0 (ETH was forwarded).
        // For a correct forwarding, the contract's balance remains unchanged (ethAmount sent in, ethAmount forwarded out).
        // The buggy version keeps the ETH, so balanceAfter == balanceBefore + ethAmount.
        // Thus the rule that balance change == 0 holds for the reference and fails for the mutant.
        assertTrue(balanceAfter - balanceBefore == 0);
    }
}

