pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, bytes memory data, uint256 amount) public {
        // restrict amount to a plausible range, keeping it wide
        bound(amount, 1, 100 ether);
        // ensure we are the Owner to pass the require
        vm.prank(address(this));
        uint256 balBefore = address(c).balance;
        // call Command with fuzzed parameters; we must route the call through a
        // helper that does NOT revert, because a fuzzed address is an EOA that
        // always succeeds on a low-level call, and we need to isolate the ETH
        // forwarding difference (the bug is about the low-level call being
        // removed). So we deploy a benign recipient.
        Sink sink = new Sink();
        c.Command{value: amount}(address(sink), data);
        uint256 balAfter = address(c).balance;
        // For the reference, the ETH is forwarded: balAfter < balBefore.
        // For the bug, the ETH is kept: balAfter == balBefore + amount.
        assertTrue(balAfter < balBefore);
    }
}

contract Sink {
    fallback() external payable {}
}

