import {C} from "../src/C_under_test.sol";

contract BalanceProbe {
    function balance() external payable returns (uint256) {
        return address(this).balance;
    }
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address target) public {
        // Keep amount admissible and non-zero so forwarding matters
        vm.assume(amount > 0 && amount <= address(this).balance);
        BalanceProbe probe = new BalanceProbe();
        vm.deal(target, amount);
        vm.prank(target);
        c.Command{value: amount}(address(probe), abi.encodeWithSelector(BalanceProbe.balance.selector));
        uint256 probeBalance = probe.balance();
        // The general rule: probe received exactly the forwarded msg.value
        assertTrue(probeBalance == amount);
    }
}

