    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 donated, uint256 sent, address adr) public {
        // Keep adr distinct from test contract and Owner, but fuzz it widely
        vm.assume(adr != address(0));
        vm.assume(adr != address(this));
        vm.assume(adr != address(c));
        // Donate some Ether so balance is not zero; cap to avoid overflow
        donated = bound(donated, 0, type(uint128).max);
        sent = bound(sent, 0, type(uint128).max);
        // Fund the test contract and donate to c
        vm.deal(address(this), donated);
        (bool okD,) = address(c).call{value: donated}("");
        require(okD, "donate failed");
        // Prerequisite: sent >= address(this).balance => must enter the if branch
        uint256 balBefore = address(c).balance;
        vm.assume(sent >= balBefore);
        vm.deal(address(this), sent);
        // Call multiplicate; record success
        bool succeeded;
        try c.multiplicate{value: sent}(adr) {
            succeeded = true;
        } catch {
            succeeded = false;
        }
        // Rule: the call must succeed (not revert) when the condition is met
        assertTrue(succeeded);
    }
