pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address adr) public {
        vm.assume(adr != address(0) && adr != address(c));
        vm.assume(amount > 0);
        // Fund the contract to some non-zero balance so the condition msg.value >= address(this).balance can be satisfied
        vm.deal(address(c), 10 ether);
        vm.deal(address(this), amount);
        vm.prank(address(this));
        bool ok;
        try c.multiplicate{value: amount}(adr) { ok = true; } catch { ok = false; }
        // General rule: if the call did not revert, the contract balance must be zero (all funds transferred out).
        // If it reverted, the contract balance must remain unchanged (still 10 ether).
        // The buggy version always reverts when msg.value >= balance, so this rule breaks: a non-reverting call should leave zero balance, but bug reverts, leaving balance unchanged.
        assertTrue(!ok || address(c).balance == 0);
    }
}

