import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 msgValue, address payable adr) public {
        // Ensure we don't overflow total balance
        vm.assume(msgValue <= type(uint120).max);
        vm.assume(msgValue >= address(c).balance);
        // Ensure adr is not the contract itself to avoid self-transfer complications
        vm.assume(adr != address(c));
        vm.assume(adr != address(0));

        // Fund the sender and make the call
        address sender = address(0x1234);
        vm.deal(sender, msgValue);
        vm.deal(address(c), 0); // start with zero balance, satisfy msgValue >= balance
        vm.prank(sender);
        bool ok;
        try c.multiplicate{value: msgValue}(adr) { ok = true; } catch { ok = false; }
        // The reference never reverts in this path; the buggy always reverts.
        assertTrue(ok);
    }
}

